import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api'; // Ensure you have a file to make API requests
import './Auth.css';

const Register = () => {
  const [form, setForm] = useState({ name: '', email: '', password: '' });
  const [message, setMessage] = useState('');
  const [success, setSuccess] = useState(null); // true or false
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await api.post('/auth/register', form); // Assuming you have the /auth/register API endpoint
      setSuccess(true);
      setMessage(res.data.message || 'Successfully registered!');

      // Redirect to login after 1.5 seconds
      setTimeout(() => navigate('/login'), 1500); 
    } catch (err) {
      setSuccess(false);
      setMessage(err.response?.data?.message || 'Registration failed');
    }
  };

  return (
    <div className="auth-container">
      <h2>Register</h2>
      <form className="auth-form" onSubmit={handleSubmit}>
        <input type="text" name="name" placeholder="Name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required />
        <input type="email" name="email" placeholder="Email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} required />
        <input type="password" name="password" placeholder="Password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} required />
        <button type="submit">Register</button>
      </form>
      {message && (
        <p className={`auth-message ${success ? 'success' : 'error'}`}>
          {message}
        </p>
      )}
    </div>
  );
};

export default Register;
